import sys

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0

        # Frequency maps for coprime logic
        # d = 3, 6 (mod 3)
        freq3 = {0: 1}
        current_p3 = 0

        # d = 7 (mod 7)
        freq7 = {0: 1}
        current_p7 = 0
        inv10_7 = 5 # 10^-1 mod 7
        inv_pow7 = 1

        # d = 9 (mod 9)
        freq9 = {0: 1}
        current_p9 = 0

        for j, char in enumerate(s):
            digit = int(char)

            # Skip if last digit is 0
            if digit == 0:
                continue

            # d = 1, 2, 5: All substrings ending at j are divisible
            if digit in (1, 2, 5):
                ans += (j + 1)

            # d = 3, 6: Divisible by 3
            # P_j = (P_{j-1} + digit) % 3
            # Condition: P_j == P_{i-1}
            current_p3 = (current_p3 + digit) % 3
            if digit in (3, 6):
                ans += freq3.get(current_p3, 0)
            freq3[current_p3] = freq3.get(current_p3, 0) + 1

            # d = 4: Divisible by 4 depends on last 2 digits
            if digit == 4:
                if j >= 1:
                    val2 = int(s[j-1:j+1])
                    if val2 % 4 == 0:
                        ans += (j + 1)
                    else:
                        ans += 1
                else:
                    ans += 1

            # d = 7: Coprime logic
            # Q_j = P_j * (10^-1)^(j+1)
            current_p7 = (current_p7 * 10 + digit) % 7
            inv_pow7 = (inv_pow7 * inv10_7) % 7
            q_j = (current_p7 * inv_pow7) % 7
            if digit == 7:
                ans += freq7.get(q_j, 0)
            freq7[q_j] = freq7.get(q_j, 0) + 1

            # d = 8: Divisible by 8 depends on last 3 digits
            if digit == 8:
                if j >= 2:
                    val3 = int(s[j-2:j+1])
                    if val3 % 8 == 0:
                        ans += (j + 1)
                    elif j >= 1:
                        val2 = int(s[j-1:j+1])
                        if val2 % 8 == 0:
                            ans += 2
                        else:
                            ans += 1
                    else:
                        ans += 1
                elif j >= 1:
                    val2 = int(s[j-1:j+1])
                    if val2 % 8 == 0:
                        ans += 2
                    else:
                        ans += 1
                else:
                    ans += 1

            # d = 9: Divisible by 9
            # P_j = (P_{j-1} + digit) % 9
            # Condition: P_j == P_{i-1}
            current_p9 = (current_p9 + digit) % 9
            if digit == 9:
                ans += freq9.get(current_p9, 0)
            freq9[current_p9] = freq9.get(current_p9, 0) + 1

        return ans

